// Embeds Bricolage Grotesque (WOFF, latin + latin-ext) as base64 for social preview images.
// Cloudflare Workers has no file system, so fonts cannot be read at request time.
//   node scripts/build-og-fonts.mjs
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const dir = path.join(root, "node_modules", "@fontsource", "bricolage-grotesque", "files");
const b64 = (f) => fs.readFileSync(path.join(dir, f)).toString("base64");
const out = [
  "// Generated by scripts/build-og-fonts.mjs — do not edit by hand.",
  `export const BRICOLAGE_700 = ${JSON.stringify(b64("bricolage-grotesque-latin-700-normal.woff"))};`,
  `export const BRICOLAGE_700_EXT = ${JSON.stringify(b64("bricolage-grotesque-latin-ext-700-normal.woff"))};`,
  `export const BRICOLAGE_500 = ${JSON.stringify(b64("bricolage-grotesque-latin-500-normal.woff"))};`,
  `export const BRICOLAGE_500_EXT = ${JSON.stringify(b64("bricolage-grotesque-latin-ext-500-normal.woff"))};`,
  "",
].join("\n");
fs.writeFileSync(path.join(root, "src", "lib", "og", "fonts.ts"), out);
console.log(`src/lib/og/fonts.ts (${Math.round(out.length / 1024)} KB)`);
